#!/usr/bin/env python3
"""Compute ground truth for CSX-177 Q2 from local report evidence."""

from __future__ import annotations

import html
import json
import re
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-177_Q2"
EVENT_ID = "CSX-177"
TASK_DIR = Path(__file__).resolve().parent
ROOT = TASK_DIR.parents[2]
PACKAGE = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = TASK_DIR / "computed_gt.json"

ANCHOR_JSON = "data/event_reports/event_reports_003_Locked_event_anchor_2022_Uljin-Samcheok_wildfire_in_South_Korea.json"
REPORT_HTML = "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html"

SOURCE_FILES = [
    "metadata/event.json",
    ANCHOR_JSON,
    REPORT_HTML,
]


def load_json(relative_path: str) -> Any:
    with (PACKAGE / relative_path).open("r", encoding="utf-8", errors="replace") as handle:
        return json.load(handle)


def load_text(relative_path: str) -> str:
    return (PACKAGE / relative_path).read_text(encoding="utf-8", errors="replace")


def clean_html(raw: str) -> str:
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", raw)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def report_text() -> str:
    raw = load_text(REPORT_HTML)
    paragraphs = re.findall(r"<p[^>]*>(.*?)</p>", raw, flags=re.I | re.S)
    return " ".join(clean_html(paragraph) for paragraph in paragraphs)


def inclusive_days(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days + 1


def first_int(pattern: str, text: str, label: str) -> int:
    match = re.search(pattern, text, flags=re.I)
    if not match:
        raise ValueError(f"missing {label}")
    return int(match.group(1).replace(",", ""))


def first_march_day(pattern: str, text: str, label: str) -> str:
    match = re.search(pattern, text, flags=re.I)
    if not match:
        raise ValueError(f"missing {label}")
    return f"2022-03-{int(match.group(1)):02d}"


def rounded(value: float, digits: int = 2) -> float:
    return round(float(value), digits)


def build_ground_truth() -> dict[str, Any]:
    event = load_json("metadata/event.json")
    anchor = load_json(ANCHOR_JSON)
    text = report_text()

    start = anchor["temporal_window"]["start_date"]
    end = anchor["temporal_window"]["end_date"]
    n_days = inclusive_days(start, end)

    first_moderation_day = first_march_day(
        r"By March ([0-9]+)\s*,?\s*smoke had thinned some as winds slackened and the weather turned foggy",
        text,
        "first moderation day",
    )
    continued_fire_activity = bool(
        re.search(r"satellites continued to detect fire activity", text, flags=re.I)
    )
    early_active_days = inclusive_days(start, first_moderation_day)
    early_fraction = rounded(early_active_days / n_days, 3)
    late_days = n_days - early_active_days
    late_fraction = rounded(late_days / n_days, 3)

    early_anchors = {
        "dry_weather_text": bool(re.search(r"dry weather", text, flags=re.I)),
        "strong_winds_text": bool(re.search(r"strong winds", text, flags=re.I)),
        "westerly_smoke_transport_text": bool(
            re.search(r"westerly winds sent smoke plumes streaming toward southern Japan", text, flags=re.I)
        ),
    }
    late_anchors = {
        "smoke_thinned_text": bool(re.search(r"smoke had thinned", text, flags=re.I)),
        "winds_slackened_text": bool(re.search(r"winds slackened", text, flags=re.I)),
        "foggy_weather_text": bool(re.search(r"weather turned foggy", text, flags=re.I)),
    }
    a_count = sum(1 for value in early_anchors.values() if value)
    m_count = sum(1 for value in late_anchors.values() if value)
    continuation_discount = 0.5 if continued_fire_activity else 1.0

    burned_hectares = first_int(r"charred nearly ([0-9,]+) hectares", text, "burned hectares")
    burned_area_kha = rounded(burned_hectares / 1000.0, 3)

    early_score = a_count * early_fraction * burned_area_kha
    late_score = m_count * late_fraction * 5.0 * continuation_discount
    ratio = early_score / late_score
    diagnosis = (
        "early_dry_wind_spread_dominant"
        if early_score > late_score and ratio >= 1.5 and continued_fire_activity
        else "late_moderation_or_mixed_control"
    )
    top_evidence_stage = "early_dry_wind_fire_spread" if early_score > late_score else "late_wind_slackening_fog_moderation"

    primary_gt = {
        "formula": "early_spread_score = A * (E / N) * Hkha; late_moderation_score = M * ((N - E) / N) * 5 * C",
        "mechanism_competition": [
            {
                "mechanism": "early_dry_wind_fire_spread",
                "supporting_values": {
                    "A_report_anchor_count": a_count,
                    "E_early_active_days": early_active_days,
                    "N_event_days": n_days,
                    "H_burned_area_kha": burned_area_kha,
                    "score": rounded(early_score, 2),
                },
                "status": "dominant",
            },
            {
                "mechanism": "late_wind_slackening_fog_moderation",
                "supporting_values": {
                    "M_moderation_anchor_count": m_count,
                    "late_days": late_days,
                    "continuation_discount": continuation_discount,
                    "score": rounded(late_score, 2),
                },
                "status": "secondary_moderation_not_dominant",
            },
        ],
        "phase_scores": {
            "early_spread_score": rounded(early_score, 2),
            "late_moderation_score": rounded(late_score, 2),
            "early_late_ratio": rounded(ratio, 2),
        },
        "top_evidence_stage": top_evidence_stage,
        "first_moderation_day": first_moderation_day,
        "diagnosis": diagnosis,
        "computed_consequence": (
            "The early dry-wind mechanism dominates because the report gives all early spread anchors, "
            "large burned area, and continued fire detection even on the first moderation day."
        ),
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Mechanism schema and diagnosis",
                "points": 3,
                "description": "Provides the requested JSON mechanism competition and final diagnosis early_dry_wind_spread_dominant.",
                "partial_credit": "Award partial credit for the correct diagnosis with missing or malformed ledger fields.",
            },
            {
                "name": "Early spread evidence",
                "points": 4,
                "description": "Finds all three early anchors: dry weather, strong winds, and westerly smoke transport toward southern Japan.",
                "partial_credit": "Award 1 point for each correct anchor and 1 point for the correct count A=3.",
            },
            {
                "name": "Late moderation evidence",
                "points": 3,
                "description": "Finds smoke thinning, winds slackening, foggy weather, and continued fire activity on March 7.",
                "partial_credit": "Award partial credit for correct moderation anchors but missing the continued-fire discount.",
            },
            {
                "name": "Timing and burned-area calculations",
                "points": 4,
                "description": "Computes N=10, E=4, late_days=6, Hkha=17.0, early_fraction=0.4, and late_fraction=0.6.",
                "partial_credit": "Award partial credit for correct dates or burned area with one arithmetic or conversion error.",
            },
            {
                "name": "Score comparison",
                "points": 3,
                "description": "Computes early score 20.40, late score 4.50, ratio 4.53, and applies the >=1.5 dominance rule.",
                "partial_credit": "Award partial credit for a correct qualitative comparison with one incorrect score.",
            },
            {
                "name": "Computed consequence",
                "points": 2,
                "description": "Keeps the consequence tied to the computed mechanism competition rather than action guidance or broad wildfire explanation.",
                "partial_credit": "Award partial credit for a mostly numeric answer with extra but harmless prose.",
            },
            {
                "name": "Extra-claim control",
                "points": 1,
                "description": "Avoids claiming the score is calibrated fire danger, exact perimeter, exact smoke dose, or a measured health impact.",
                "partial_credit": "Award no credit if the answer makes multiple unsupported escalations.",
            },
        ],
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "mechanism_competition",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": {
                "start_date": start,
                "end_date": end,
                "inclusive_days": n_days,
            },
            "early_anchors": early_anchors,
            "late_anchors": late_anchors,
            "continued_fire_activity": continued_fire_activity,
            "burned_hectares": burned_hectares,
            "threshold_ledger": {
                "early_score_higher": early_score > late_score,
                "ratio_at_least_1_5": ratio >= 1.5,
                "continued_fire_on_first_moderation_day": continued_fire_activity,
                "diagnosis": diagnosis,
            },
        },
        "numeric_tolerances": {
            "phase_scores.early_spread_score": 0.05,
            "phase_scores.late_moderation_score": 0.05,
            "phase_scores.early_late_ratio": 0.02,
            "mechanism_competition.supporting_values.H_burned_area_kha": 0.05,
        },
        "judge_anchors": {
            "required_claims": [
                "Uses March 4-13, 2022 as a 10-day inclusive event window.",
                "Uses March 7 as the first moderation day and March 4-7 as the 4-day early active interval.",
                "Counts A=3 early anchors and M=3 late moderation anchors.",
                "Applies C=0.5 because fire activity was still detected on the moderation day.",
                "Computes early score 20.40, late score 4.50, and ratio 4.53.",
                "Diagnoses early_dry_wind_spread_dominant.",
            ],
            "forbidden_claims": [
                "Using off-event Open-Meteo, NASA POWER, GPM, or CHIRPS values as local Uljin-Samcheok daily weather.",
                "Claiming measured PM2.5 concentration, exact smoke dose, exact fire perimeter, or health outcomes.",
            ],
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": [
                "Off-event daily weather and gridded precipitation files are not used in this ground truth.",
                "The mechanism competition is computed from declared event anchor metadata and NASA Earth Observatory report text.",
            ],
        },
    }


def main() -> None:
    OUT.write_text(json.dumps(build_ground_truth(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
